-- migration_55_recipe_journal.sql
--
-- The Recipe Journal (Diário de Receitas): /diario and /en/journal, edited in Admin › Diário de Receitas.
--
--   journal_categories          the themes (Natal, Chocolate…) and the "how it is made" filters (Cru, Sem trigo, SOS-free).
--   journal_recipes             one row per recipe: photo, times, tags, price, free or premium, featured, and the PUBLIC
--                               text in each language (title, story, what makes it special). Everyone reads published ones.
--   journal_recipe_bodies       the protected part: ingredients with quantities, steps, notes, storage. Readable only
--                               through journal_has_access(): admins, free recipes, buyers of the recipe or of a
--                               collection that has it. A guessed URL or a direct API call gets nothing.
--   journal_collections         themed bundles sold as one product (+ journal_collection_recipes).
--   journal_access              who may read what: one row per purchase (written by the server with the service key when
--                               the order is created) or a gift Dolly adds by hand. A purchase counts only while its
--                               order is paid (card: status PAID; Pix: confirmed in the inbox) and not refunded.
--   journal_codes               discount codes (percent off), checked by the server.
--   journal_views               views per recipe per day, for the admin's numbers and the "most viewed" sort.
--
-- Seeded with the 7 Sweet Escape recipes in Portuguese and English (generated by tools/journal-seed.mjs from
-- src/lib/journal/seed.json). Bliss Balls and Banoffee Bars are free (they are the free-recipes sampler). ON CONFLICT
-- DO NOTHING, so running this again never overwrites Dolly's edits.
--
-- Safe to run more than once. Until it runs, the journal shows its built-in recipes and nobody can buy.

BEGIN;

CREATE EXTENSION IF NOT EXISTS pgcrypto;

-- ------------------------------------------------------------ categories
CREATE TABLE IF NOT EXISTS public.journal_categories (
    slug        text PRIMARY KEY CHECK (slug ~ '^[a-z0-9-]+$'),
    kind        text NOT NULL DEFAULT 'tema' CHECK (kind IN ('tema', 'dieta')),
    name        jsonb NOT NULL DEFAULT '{}'::jsonb,
    sort        integer NOT NULL DEFAULT 100,
    created_at  timestamptz NOT NULL DEFAULT now()
);

-- ------------------------------------------------------------ recipes
CREATE TABLE IF NOT EXISTS public.journal_recipes (
    id               uuid PRIMARY KEY DEFAULT gen_random_uuid(),
    slug             text UNIQUE NOT NULL CHECK (slug ~ '^[a-z0-9-]+$'),
    slug_en          text UNIQUE CHECK (slug_en IS NULL OR slug_en ~ '^[a-z0-9-]+$'),
    status           text NOT NULL DEFAULT 'draft' CHECK (status IN ('draft', 'published')),
    -- A date in the future = scheduled: it appears by itself at that moment.
    publish_at       timestamptz NOT NULL DEFAULT now(),
    is_free          boolean NOT NULL DEFAULT false,
    price_brl        numeric(10,2) NOT NULL DEFAULT 12.90 CHECK (price_brl >= 0),
    promo_price_brl  numeric(10,2) CHECK (promo_price_brl IS NULL OR promo_price_brl >= 0),
    is_featured      boolean NOT NULL DEFAULT false,
    sort             integer NOT NULL DEFAULT 100,
    hero_url         text,
    gallery          text[] NOT NULL DEFAULT '{}',
    video_url        text,
    prep_minutes     integer NOT NULL DEFAULT 0 CHECK (prep_minutes BETWEEN 0 AND 1440),
    cook_minutes     integer NOT NULL DEFAULT 0 CHECK (cook_minutes BETWEEN 0 AND 1440),
    chill_minutes    integer NOT NULL DEFAULT 0 CHECK (chill_minutes BETWEEN 0 AND 4320),
    difficulty       text NOT NULL DEFAULT 'facil' CHECK (difficulty IN ('facil', 'media', 'avancada')),
    categories       text[] NOT NULL DEFAULT '{}',
    tags             text[] NOT NULL DEFAULT '{}',
    -- Allergen ids from src/lib/allergens.ts.
    contains         text[] NOT NULL DEFAULT '{}',
    -- { "pt": { title, subtitle, summary, story, benefits[], yield, preview[], seo_title, seo_description }, "en": {…} }
    text             jsonb NOT NULL DEFAULT '{}'::jsonb,
    views            integer NOT NULL DEFAULT 0,
    created_at       timestamptz NOT NULL DEFAULT now(),
    updated_at       timestamptz NOT NULL DEFAULT now()
);
-- Only one featured recipe at a time.
CREATE UNIQUE INDEX IF NOT EXISTS journal_recipes_one_featured ON public.journal_recipes (is_featured) WHERE is_featured;

CREATE TABLE IF NOT EXISTS public.journal_recipe_bodies (
    recipe_id   uuid PRIMARY KEY REFERENCES public.journal_recipes(id) ON DELETE CASCADE,
    -- { "pt": { sections: [{ name, ingredients[], steps[] }], notes, storage }, "en": {…} }
    body        jsonb NOT NULL DEFAULT '{}'::jsonb,
    updated_at  timestamptz NOT NULL DEFAULT now()
);

CREATE OR REPLACE FUNCTION public.journal_touch()
RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
    NEW.updated_at := now();
    RETURN NEW;
END;
$$;
DROP TRIGGER IF EXISTS journal_recipes_touch ON public.journal_recipes;
CREATE TRIGGER journal_recipes_touch BEFORE UPDATE ON public.journal_recipes FOR EACH ROW EXECUTE FUNCTION public.journal_touch();
DROP TRIGGER IF EXISTS journal_bodies_touch ON public.journal_recipe_bodies;
CREATE TRIGGER journal_bodies_touch BEFORE UPDATE ON public.journal_recipe_bodies FOR EACH ROW EXECUTE FUNCTION public.journal_touch();

-- ------------------------------------------------------------ collections
CREATE TABLE IF NOT EXISTS public.journal_collections (
    id               uuid PRIMARY KEY DEFAULT gen_random_uuid(),
    slug             text UNIQUE NOT NULL CHECK (slug ~ '^[a-z0-9-]+$'),
    published        boolean NOT NULL DEFAULT false,
    price_brl        numeric(10,2) NOT NULL DEFAULT 29.90 CHECK (price_brl >= 0),
    promo_price_brl  numeric(10,2) CHECK (promo_price_brl IS NULL OR promo_price_brl >= 0),
    cover_url        text,
    sort             integer NOT NULL DEFAULT 100,
    -- { "pt": { title, summary, description }, "en": {…} }
    text             jsonb NOT NULL DEFAULT '{}'::jsonb,
    created_at       timestamptz NOT NULL DEFAULT now(),
    updated_at       timestamptz NOT NULL DEFAULT now()
);
DROP TRIGGER IF EXISTS journal_collections_touch ON public.journal_collections;
CREATE TRIGGER journal_collections_touch BEFORE UPDATE ON public.journal_collections FOR EACH ROW EXECUTE FUNCTION public.journal_touch();

CREATE TABLE IF NOT EXISTS public.journal_collection_recipes (
    collection_id  uuid NOT NULL REFERENCES public.journal_collections(id) ON DELETE CASCADE,
    recipe_id      uuid NOT NULL REFERENCES public.journal_recipes(id) ON DELETE CASCADE,
    sort           integer NOT NULL DEFAULT 100,
    PRIMARY KEY (collection_id, recipe_id)
);

-- ------------------------------------------------------------ access, codes, views
CREATE TABLE IF NOT EXISTS public.journal_access (
    id             uuid PRIMARY KEY DEFAULT gen_random_uuid(),
    user_id        uuid NOT NULL REFERENCES auth.users(id) ON DELETE CASCADE,
    recipe_id      uuid REFERENCES public.journal_recipes(id) ON DELETE CASCADE,
    collection_id  uuid REFERENCES public.journal_collections(id) ON DELETE CASCADE,
    -- The purchase (orders.id). NULL = a gift Dolly added by hand, valid without an order.
    order_id       uuid,
    reference      text,
    price_brl      numeric(10,2),
    code           text,
    source         text NOT NULL DEFAULT 'compra' CHECK (source IN ('compra', 'presente')),
    note           text,
    created_at     timestamptz NOT NULL DEFAULT now(),
    CHECK ((recipe_id IS NULL) <> (collection_id IS NULL))
);
CREATE INDEX IF NOT EXISTS journal_access_user ON public.journal_access (user_id);
CREATE INDEX IF NOT EXISTS journal_access_order ON public.journal_access (order_id);

CREATE TABLE IF NOT EXISTS public.journal_codes (
    code         text PRIMARY KEY CHECK (code ~ '^[A-Z0-9-]{3,30}$'),
    percent_off  integer NOT NULL CHECK (percent_off BETWEEN 1 AND 100),
    active       boolean NOT NULL DEFAULT true,
    expires_at   timestamptz,
    max_uses     integer CHECK (max_uses IS NULL OR max_uses > 0),
    note         text,
    created_at   timestamptz NOT NULL DEFAULT now()
);

CREATE TABLE IF NOT EXISTS public.journal_views (
    recipe_id  uuid NOT NULL REFERENCES public.journal_recipes(id) ON DELETE CASCADE,
    day        date NOT NULL,
    views      integer NOT NULL DEFAULT 0,
    PRIMARY KEY (recipe_id, day)
);

-- ------------------------------------------------------------ who may read a full recipe
-- Is this order paid and not refunded? Card/PayPal/Stripe: status PAID. Pix: moved past "new" in the inbox.
CREATE OR REPLACE FUNCTION public.journal_order_paid(p_order uuid)
RETURNS boolean
LANGUAGE sql
STABLE
SECURITY DEFINER
SET search_path = public
AS $$
    SELECT EXISTS (
        SELECT 1 FROM public.orders o
        WHERE o.id = p_order
          AND upper(coalesce(o.status, '')) NOT IN ('REFUNDED', 'CANCELLED')
          AND NOT EXISTS (
              SELECT 1 FROM public.inbox_status i
              WHERE i.source_table = 'orders' AND i.source_id = o.id::text AND i.status = 'cancelled'
          )
          AND (
              upper(coalesce(o.status, '')) = 'PAID'
              OR EXISTS (
                  SELECT 1 FROM public.inbox_status i
                  WHERE i.source_table = 'orders' AND i.source_id = o.id::text
                    AND i.status NOT IN ('new', 'cancelled')
              )
          )
    );
$$;
REVOKE ALL ON FUNCTION public.journal_order_paid(uuid) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.journal_order_paid(uuid) TO authenticated, service_role;

CREATE OR REPLACE FUNCTION public.journal_has_access(p_recipe uuid)
RETURNS boolean
LANGUAGE sql
STABLE
SECURITY DEFINER
SET search_path = public
AS $$
    SELECT
        public.is_admin()
        OR EXISTS (
            SELECT 1 FROM public.journal_recipes r
            WHERE r.id = p_recipe AND r.is_free AND r.status = 'published' AND r.publish_at <= now()
        )
        OR (auth.uid() IS NOT NULL AND EXISTS (
            SELECT 1 FROM public.journal_access a
            WHERE a.user_id = auth.uid()
              AND (
                  a.recipe_id = p_recipe
                  OR a.collection_id IN (SELECT cr.collection_id FROM public.journal_collection_recipes cr WHERE cr.recipe_id = p_recipe)
              )
              AND (a.order_id IS NULL OR public.journal_order_paid(a.order_id))
        ));
$$;
REVOKE ALL ON FUNCTION public.journal_has_access(uuid) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.journal_has_access(uuid) TO anon, authenticated, service_role;

-- The signed-in person's purchases (for "Minhas receitas" and the purchase history). Never anyone else's.
CREATE OR REPLACE FUNCTION public.journal_my_purchases()
RETURNS TABLE (reference text, created_at timestamptz, price_brl numeric, paid boolean, recipe_id uuid, collection_id uuid, source text)
LANGUAGE sql
STABLE
SECURITY DEFINER
SET search_path = public
AS $$
    SELECT a.reference, a.created_at, a.price_brl,
           (a.order_id IS NULL OR public.journal_order_paid(a.order_id)) AS paid,
           a.recipe_id, a.collection_id, a.source
    FROM public.journal_access a
    WHERE a.user_id = auth.uid()
    ORDER BY a.created_at DESC;
$$;
REVOKE ALL ON FUNCTION public.journal_my_purchases() FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.journal_my_purchases() TO authenticated;

-- One more view of a live recipe (by either slug). Anyone may call it; it only ever adds one.
CREATE OR REPLACE FUNCTION public.journal_count_view(p_slug text)
RETURNS void
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
    rid uuid;
BEGIN
    SELECT id INTO rid FROM public.journal_recipes
    WHERE (slug = p_slug OR slug_en = p_slug) AND status = 'published' AND publish_at <= now()
    LIMIT 1;
    IF rid IS NULL THEN RETURN; END IF;
    UPDATE public.journal_recipes SET views = views + 1 WHERE id = rid;
    INSERT INTO public.journal_views (recipe_id, day, views)
    VALUES (rid, (now() AT TIME ZONE 'America/Sao_Paulo')::date, 1)
    ON CONFLICT (recipe_id, day) DO UPDATE SET views = public.journal_views.views + 1;
END;
$$;
REVOKE ALL ON FUNCTION public.journal_count_view(text) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.journal_count_view(text) TO anon, authenticated;

-- ------------------------------------------------------------ row level security
ALTER TABLE public.journal_categories ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.journal_recipes ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.journal_recipe_bodies ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.journal_collections ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.journal_collection_recipes ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.journal_access ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.journal_codes ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.journal_views ENABLE ROW LEVEL SECURITY;

DROP POLICY IF EXISTS journal_categories_read ON public.journal_categories;
CREATE POLICY journal_categories_read ON public.journal_categories FOR SELECT USING (true);
DROP POLICY IF EXISTS journal_categories_admin ON public.journal_categories;
CREATE POLICY journal_categories_admin ON public.journal_categories FOR ALL TO authenticated USING (public.is_admin()) WITH CHECK (public.is_admin());

DROP POLICY IF EXISTS journal_recipes_read ON public.journal_recipes;
CREATE POLICY journal_recipes_read ON public.journal_recipes FOR SELECT
    USING ((status = 'published' AND publish_at <= now()) OR public.is_admin());
DROP POLICY IF EXISTS journal_recipes_admin ON public.journal_recipes;
CREATE POLICY journal_recipes_admin ON public.journal_recipes FOR ALL TO authenticated USING (public.is_admin()) WITH CHECK (public.is_admin());

DROP POLICY IF EXISTS journal_bodies_read ON public.journal_recipe_bodies;
CREATE POLICY journal_bodies_read ON public.journal_recipe_bodies FOR SELECT USING (public.journal_has_access(recipe_id));
DROP POLICY IF EXISTS journal_bodies_admin ON public.journal_recipe_bodies;
CREATE POLICY journal_bodies_admin ON public.journal_recipe_bodies FOR ALL TO authenticated USING (public.is_admin()) WITH CHECK (public.is_admin());

DROP POLICY IF EXISTS journal_collections_read ON public.journal_collections;
CREATE POLICY journal_collections_read ON public.journal_collections FOR SELECT USING (published OR public.is_admin());
DROP POLICY IF EXISTS journal_collections_admin ON public.journal_collections;
CREATE POLICY journal_collections_admin ON public.journal_collections FOR ALL TO authenticated USING (public.is_admin()) WITH CHECK (public.is_admin());

DROP POLICY IF EXISTS journal_collection_recipes_read ON public.journal_collection_recipes;
CREATE POLICY journal_collection_recipes_read ON public.journal_collection_recipes FOR SELECT USING (true);
DROP POLICY IF EXISTS journal_collection_recipes_admin ON public.journal_collection_recipes;
CREATE POLICY journal_collection_recipes_admin ON public.journal_collection_recipes FOR ALL TO authenticated USING (public.is_admin()) WITH CHECK (public.is_admin());

DROP POLICY IF EXISTS journal_access_own ON public.journal_access;
CREATE POLICY journal_access_own ON public.journal_access FOR SELECT TO authenticated USING (user_id = auth.uid() OR public.is_admin());
DROP POLICY IF EXISTS journal_access_admin ON public.journal_access;
CREATE POLICY journal_access_admin ON public.journal_access FOR ALL TO authenticated USING (public.is_admin()) WITH CHECK (public.is_admin());

DROP POLICY IF EXISTS journal_codes_admin ON public.journal_codes;
CREATE POLICY journal_codes_admin ON public.journal_codes FOR ALL TO authenticated USING (public.is_admin()) WITH CHECK (public.is_admin());

DROP POLICY IF EXISTS journal_views_admin ON public.journal_views;
CREATE POLICY journal_views_admin ON public.journal_views FOR SELECT TO authenticated USING (public.is_admin());

-- New tables need explicit Data API grants (Supabase, since 2026-10-30). RLS above still decides the rows.
GRANT SELECT ON public.journal_categories, public.journal_recipes, public.journal_recipe_bodies,
                public.journal_collections, public.journal_collection_recipes TO anon;
GRANT SELECT, INSERT, UPDATE, DELETE ON public.journal_categories, public.journal_recipes, public.journal_recipe_bodies,
                public.journal_collections, public.journal_collection_recipes, public.journal_access,
                public.journal_codes, public.journal_views TO authenticated;
GRANT SELECT, INSERT, UPDATE, DELETE ON public.journal_categories, public.journal_recipes, public.journal_recipe_bodies,
                public.journal_collections, public.journal_collection_recipes, public.journal_access,
                public.journal_codes, public.journal_views TO service_role;

