INSERT INTO public.journal_recipes (slug, slug_en, status, publish_at, is_free, price_brl, is_featured, sort, hero_url, gallery, prep_minutes, cook_minutes, chill_minutes, difficulty, categories, tags, contains, text)
SELECT 'quadradinhos-paraiso-coco-abacaxi', 'coco-pineapple-paradise-squares', 'published', now() - interval '60 minutes', false, 12.9, false, 10, '/ebook/sweet-escape/yellow-plate.webp', ARRAY['/ebook/sweet-escape/yellow-stack.webp', '/ebook/sweet-escape/yellow.webp']::text[], 25, 0, 240, 'facil', ARRAY['frutas-tropicais', 'verao', 'brownies-barrinhas', 'cru', 'sem-forno', 'sem-trigo', 'sos-free']::text[], ARRAY['Sweet Escape', 'Abacaxi', 'Cúrcuma']::text[], ARRAY['castanhas', 'coco']::text[],
    '{"pt":{"title":"Quadradinhos Paraíso de Coco e Abacaxi","subtitle":"com cobertura de coco e cúrcuma","summary":"Uma base de tâmara e amêndoa, um creme de caju com abacaxi maduro e um polvilhado dourado de coco. Sem forno, direto do freezer.","story":"O abacaxi é a minha fruta favorita no mundo. É a mordida mais completa da natureza: doce, azedinho, suculento, fibroso e vibrante. Nativo da América do Sul e amado em todos os climas tropicais, o abacaxi já foi tão valorizado na Europa que era considerado símbolo de luxo e hospitalidade.\n\nO abacaxi cresce no chão, não em árvores, e é considerado uma flor. Para escolher um maduro, cheire a base (tem que ter um aroma doce e perfumado), aperte de leve para ver se ele cede um pouco e procure a casca dourada com as folhas bem verdes. Se tiver cheiro azedo ou de fermentado, já passou do ponto.\n\nQuando eu estava grávida, não conseguia ficar sem o meu abacaxi de todo dia, e espero que meus bebês peguem o mesmo gosto por essa fruta mágica.","benefits":["Abacaxi: rico em vitamina C e bromelina, que ajudam na digestão e na imunidade.","Castanha-de-caju: gorduras vegetais, magnésio e proteína, para saciedade e energia.","Cúrcuma: uma raiz dourada conhecida pelas propriedades anti-inflamatórias e antioxidantes.","Tâmaras e uvas-passas: os adoçantes da natureza, com fibras, ferro e minerais.","Coco: gorduras boas e fibras, que ajudam na digestão e na saciedade."],"yield":"8 porções","preview":["1 xícara de tâmaras macias sem caroço (eu prefiro medjool)","¾ xícara de amêndoas cruas","¾ xícara de coco ralado","½ colher (chá) de canela"],"search":"abacaxi amêndoas baunilha brancas caju canela caroço castanhas coco cruas cítricos cúrcuma decorar desidratado extrato filtrada flor gengibre macias natural passas ralado raspas tâmaras uvas água","count":14},"en":{"title":"Sun-Kissed Coco-Pineapple Paradise Squares","subtitle":"with turmeric spiced coconut topping","summary":"A date and almond base, a cashew cream with ripe pineapple and a golden dusting of coconut. No oven, straight from the freezer.","story":"Pineapple is my favorite fruit in the world. It''s nature''s most complete bite: sweet, tangy, juicy, fibrous and vibrant. Native to South America and beloved across tropical climates, the pineapple was once so prized in Europe it was considered a symbol of luxury and hospitality.\n\nPineapples grow on the ground, not on trees, and are considered a flower. To select a ripe one, look for a sweet, fragrant smell at the base, a slight give when squeezed, and golden skin with vibrant green leaves. If it smells sour or fermented, it''s past its peak.\n\nWhen I was pregnant I couldn''t get enough of my daily pineapple, and I am hoping my babies will develop the same taste for its incredible magic.","benefits":["Pineapple: rich in vitamin C and bromelain, which aid digestion and support immunity.","Cashews: plant-based fats, magnesium and protein to keep you full and energized.","Turmeric: a golden root known for its anti-inflammatory and antioxidant properties.","Dates and raisins: nature''s sweeteners, with fiber, iron and natural minerals.","Coconut: healthy fats and fiber, supporting digestion and satiety."],"yield":"Serves 8","preview":["1 cup soft pitted dates (I prefer medjool)","¾ cup raw almonds","¾ cup shredded coconut","½ tsp cinnamon"],"search":"almonds cashews cinnamon citrus coconut dates decorate dried extract filtered flower ginger natural pineapple pitted powder raisins shredded slice soft turmeric vanilla water white zest","count":14}}'::jsonb
ON CONFLICT (slug) DO NOTHING;
INSERT INTO public.journal_recipe_bodies (recipe_id, body)
SELECT id, '{"pt":{"sections":[{"name":"Base","ingredients":["1 xícara de tâmaras macias sem caroço (eu prefiro medjool)","¾ xícara de amêndoas cruas","¾ xícara de coco ralado","½ colher (chá) de canela","1 colher (chá) de extrato natural de baunilha"],"steps":["Bata todos os ingredientes no processador até virar uma farofa úmida, que gruda quando você aperta.","Pressione bem em uma forma quadrada de silicone ou forrada com papel-manteiga e leve ao freezer para firmar enquanto prepara a camada de creme."]},{"name":"Camada de creme","ingredients":["1 xícara de castanhas-de-caju cruas (de molho por 4–6 horas ou em água quente por 15 minutos, depois escorridas)","1 xícara de abacaxi fresco e maduro picado","2 colheres (sopa) de uvas-passas brancas","1 colher (chá) de cúrcuma em pó","½ colher (chá) de extrato natural de baunilha","3–4 colheres (sopa) de água filtrada (ajuste a cremosidade)"],"steps":["Bata todos os ingredientes até obter um creme liso e aveludado. Prove e ajuste a textura com água, se precisar.","Despeje sobre a base e alise o topo.","Congele por 3–4 horas ou até firmar."]},{"name":"Cobertura","ingredients":["¼ xícara de coco ralado","½ colher (chá) de cúrcuma","Opcional: uma pitada de gengibre em pó ou raspas de cítricos, e uma flor de abacaxi desidratado para decorar"],"steps":["Misture o coco com a cúrcuma e polvilhe por igual por cima antes de servir. Dá um acabamento dourado e alegre e uma leve crocância."]}],"notes":"Corte em quadradinhos ainda congelado, com uma faca passada em água quente: o corte sai limpo.","storage":"Freezer, em pote fechado, por até 1 mês. Tire 10 minutos antes de comer."},"en":{"sections":[{"name":"Base layer","ingredients":["1 cup soft pitted dates (I prefer medjool)","¾ cup raw almonds","¾ cup shredded coconut","½ tsp cinnamon","1 tsp natural vanilla extract"],"steps":["Blend all ingredients in a food processor until a sticky, crumbly dough forms.","Press firmly into a parchment-lined or silicone square dish and set aside in the freezer to firm up while making the cream layer."]},{"name":"Cream layer","ingredients":["1 cup raw cashews (soaked 4–6 hours or in hot water for 15 minutes, then drained)","1 cup chopped fresh ripe pineapple","2 tbsp white raisins","1 tsp turmeric powder","½ tsp natural vanilla extract","3–4 tbsp filtered water (adjust for creaminess)"],"steps":["Blend all ingredients until silky smooth and creamy. Taste and adjust the texture with water as needed.","Pour over the base and smooth the top.","Freeze for 3–4 hours or until firm."]},{"name":"Topping","ingredients":["¼ cup shredded coconut","½ tsp turmeric","Optional: a pinch of ginger powder or fresh citrus zest, and a dried pineapple flower slice to decorate"],"steps":["Mix the coconut with the turmeric and sprinkle evenly on top before serving. It gives a cheerful golden finish and a soft crunch."]}],"notes":"Cut into squares while still frozen, with a knife dipped in hot water, for clean edges.","storage":"Freezer, in a closed container, for up to 1 month. Take out 10 minutes before eating."}}'::jsonb FROM public.journal_recipes WHERE slug = 'quadradinhos-paraiso-coco-abacaxi'
ON CONFLICT (recipe_id) DO NOTHING;

-- Muffins de Manga com Especiarias Chai
INSERT INTO public.journal_recipes (slug, slug_en, status, publish_at, is_free, price_brl, is_featured, sort, hero_url, gallery, prep_minutes, cook_minutes, chill_minutes, difficulty, categories, tags, contains, text)
SELECT 'muffins-de-manga-chai', 'chai-spiced-mango-muffins', 'published', now() - interval '50 minutes', false, 12.9, false, 20, '/ebook/sweet-escape/orange.webp', ARRAY['/ebook/sweet-escape/orange-close.webp']::text[], 25, 25, 0, 'facil', ARRAY['frutas-tropicais', 'cafe-da-manha', 'outono', 'lanche-infantil', 'sem-trigo', 'sos-free']::text[], ARRAY['Sweet Escape', 'Manga', 'Especiarias']::text[], ARRAY['castanhas', 'aveia']::text[],
    '{"pt":{"title":"Muffins de Manga com Especiarias Chai","subtitle":"com chantili de caju, laranja-sanguínea e cenoura","summary":"Muffins de aveia e amêndoa adoçados só com caramelo de tâmara, cheios de manga e de canela, cravo e noz-moscada. Por cima, um chantili laranja de castanha-de-caju.","story":"A manga é o sol tropical em forma de fruta: doce, suculenta e explodindo de cor. Nativa do Sul da Ásia, mas amada em todos os trópicos, é cultivada há mais de 4.000 anos e já foi considerada símbolo de amor e prosperidade.\n\nPara escolher a manga perfeita, aperte de leve e veja se está macia, sinta o perfume doce e procure uma casca com tom dourado-alaranjado e pontinhos amarelos. Evite as totalmente verdes ou com manchas escuras e moles.\n\nEu adoro manga pela doçura tropical e pela energia alegre: ela traz luz para a cozinha, como um pequeno sol em cada mordida.","benefits":["Manga: vitamina C, vitamina A, fibras e antioxidantes.","Castanha-de-caju: gorduras boas, magnésio e proteína.","Laranja-sanguínea: vitamina C e antocianinas.","Cenoura: betacaroteno, fibras e fitonutrientes.","Canela, cravo e noz-moscada: aquecem e ajudam na digestão."],"yield":"8–10 muffins","preview":["½ xícara de aveia em flocos, triturada","½ xícara de farinha de amêndoas","10 tâmaras macias sem caroço, batidas com 3–4 colheres (sopa) de água filtrada e 1 colher (chá) de extrato de baunilha (vira uma calda de caramelo)","1 colher (sopa) de canela"],"search":"amêndoas aveia batidas baunilha brancas caju canela caroço castanhas cenoura cravo cremoso cruas cubos extrato farinha fermento ficar filtrada flocos grande laranja macias manga moscada passas pequena ralada raspas sanguínea suco todo triturada tâmaras uvas água","count":13},"en":{"title":"Chai Spiced Mango Muffins","subtitle":"with blood orange and carrot cashew cream whip","summary":"Oat and almond muffins sweetened only with date caramel, full of mango, cinnamon, cloves and nutmeg, topped with an orange cashew whip.","story":"Mangoes are the ultimate tropical sunshine in a fruit: sweet, juicy and bursting with color. Native to South Asia but beloved across the tropics, they have been cultivated for over 4,000 years and were once a symbol of love and prosperity.\n\nTo select a perfect mango, gently squeeze for a slight softness, inhale its sweet fragrance and look for a golden-orange blush with little yellow dots. Avoid ones that are completely green or have soft, dark spots.\n\nI adore mangoes for their tropical sweetness and cheerful energy: they bring light into the kitchen, like a little sun in every bite.","benefits":["Mango: vitamin C, vitamin A, fiber and antioxidants.","Cashews: healthy fats, magnesium and protein.","Blood orange: vitamin C and anthocyanins.","Carrot: beta-carotene, fiber and phytonutrients.","Cinnamon, cloves and nutmeg: warming and digestive-friendly."],"yield":"Makes 8–10 muffins","preview":["½ cup oats, ground in a blender or food processor","½ cup almond flour","10 soft pitted dates, blended with 3–4 tbsp filtered water and 1 tsp vanilla extract into a caramel sauce","1 tbsp cinnamon"],"search":"almond baking blended blender blood caramel carrot cashews cinnamon cloves creaminess dates diced extract filtered flour food grated ground juice mango nutmeg oats orange pitted plus powder processor raisins sauce soft vanilla water white zest","count":13}}'::jsonb
ON CONFLICT (slug) DO NOTHING;
INSERT INTO public.journal_recipe_bodies (recipe_id, body)
SELECT id, '{"pt":{"sections":[{"name":"Massa","ingredients":["½ xícara de aveia em flocos, triturada","½ xícara de farinha de amêndoas","10 tâmaras macias sem caroço, batidas com 3–4 colheres (sopa) de água filtrada e 1 colher (chá) de extrato de baunilha (vira uma calda de caramelo)","1 colher (sopa) de canela","½ colher (chá) de cravo em pó","½ colher (chá) de noz-moscada","1 colher (chá) de fermento em pó","1 manga grande e madura em cubos, com todo o suco"],"steps":["Preaqueça o forno a 180 °C e separe forminhas de silicone para muffin.","Bata a aveia e a farinha de amêndoas até ficar bem fino.","Numa tigela, misture as farinhas com a calda de caramelo de tâmara e as especiarias. Acrescente o fermento, os cubos de manga e o suco, incorporando com delicadeza.","Divida a massa igualmente nas forminhas.","Asse por 20–25 minutos, até dourar e firmar.","Deixe esfriar completamente antes de decorar."]},{"name":"Chantili","ingredients":["1 xícara de castanhas-de-caju cruas (de molho por 4–6 horas ou em água quente por 15 minutos, depois escorridas)","1 laranja-sanguínea, suco e raspas","1 cenoura pequena ralada","2–4 colheres (sopa) de uvas-passas brancas (depende do quanto você gosta de doce)","2–3 colheres (sopa) de água, até ficar cremoso"],"steps":["Bata todos os ingredientes até ficar liso e cremoso, acrescentando água aos poucos até chegar à textura desejada.","Aplique com saco de confeitar ou espalhe sobre os muffins já frios. Finalize com alguns cubinhos de manga que sobraram."]}],"notes":"Sem laranja-sanguínea? Use uma laranja comum bem madura, ou meia laranja e meia tangerina.","storage":"Geladeira, em pote fechado, por até 3 dias (o chantili por cima). Sem chantili, os muffins congelam bem por 1 mês."},"en":{"sections":[{"name":"Batter","ingredients":["½ cup oats, ground in a blender or food processor","½ cup almond flour","10 soft pitted dates, blended with 3–4 tbsp filtered water and 1 tsp vanilla extract into a caramel sauce","1 tbsp cinnamon","½ tsp ground cloves","½ tsp nutmeg","1 tsp baking powder","1 large ripe mango, diced, plus all its juice"],"steps":["Preheat the oven to 180 °C (350 °F) and line silicone muffin cups.","Blend the oats and almond flour until fine.","In a bowl, mix the flour blend with the spiced date-caramel sauce. Add the baking powder, mango cubes and juice, gently folding together.","Divide the batter evenly into the muffin cups.","Bake for 20–25 minutes until golden and set.","Let cool completely before decorating."]},{"name":"Whipped topping","ingredients":["1 cup raw cashews (soaked 4–6 hours or in hot water for 15 minutes, then drained)","1 blood orange, juice and zest","1 small carrot, grated","2–4 tbsp white raisins (depending on how sweet you like it)","2–3 tbsp water, as needed for creaminess"],"steps":["Blend all ingredients until smooth and creamy, adding water gradually to reach the texture you like.","Pipe or spread over the cooled muffins. Finish with a few leftover mango cubes."]}],"notes":"No blood orange? Use a very ripe regular orange, or half an orange and half a tangerine.","storage":"Fridge, in a closed container, for up to 3 days (with the topping). Without the topping the muffins freeze well for a month."}}'::jsonb FROM public.journal_recipes WHERE slug = 'muffins-de-manga-chai'
ON CONFLICT (recipe_id) DO NOTHING;

-- Bliss Balls Azedinhas de Frutas Vermelhas
INSERT INTO public.journal_recipes (slug, slug_en, status, publish_at, is_free, price_brl, is_featured, sort, hero_url, gallery, prep_minutes, cook_minutes, chill_minutes, difficulty, categories, tags, contains, text)
SELECT 'bliss-balls-frutas-vermelhas', 'red-berry-bliss-balls', 'published', now() - interval '40 minutes', true, 12.9, NOT EXISTS (SELECT 1 FROM public.journal_recipes WHERE is_featured), 30, '/ebook/sweet-escape/red.webp', ARRAY['/ebook/sweet-escape/red-scatter.webp']::text[], 20, 0, 30, 'facil', ARRAY['frutas-tropicais', 'energy-bites', 'natal', 'festas', 'lanche-infantil', 'cru', 'sem-forno', 'sem-trigo', 'sos-free']::text[], ARRAY['Sweet Escape', 'Frutas vermelhas', 'Natal']::text[], ARRAY['castanhas', 'coco']::text[],
    '{"pt":{"title":"Bliss Balls Azedinhas de Frutas Vermelhas","subtitle":"docinhos que parecem joias, com cereja, morango, cranberry e beterraba","summary":"Bolinhas cruas de amêndoa e coco, vermelhas de cereja e morango, cobertas de framboesa. Vinte minutos, sem forno, e elas somem da mesa de Natal antes de tudo.","story":"As frutas vermelhas são as pequenas joias da natureza: vibrantes, azedinhas e cheias de sabor. Na Europa medieval, o morango era associado a Vênus, símbolo do amor e da beleza, enquanto as cerejas eram cultivadas nos mosteiros tanto para a cozinha quanto para fins medicinais.\n\nOs tons vermelhos intensos indicam a presença de antocianinas. A cereja é rica em melatonina, o cranberry dá um toque azedinho e a beterraba em pó acrescenta uma doçura terrosa e realça a cor.\n\nEstas bliss balls são como joias comestíveis: um docinho que nos conecta a séculos de amor pelas frutas vermelhas enquanto nutre o seu corpo hoje.","benefits":["Cereja: antioxidantes e melatonina, para o sono e a recuperação.","Morango: vitamina C, fibras e polifenóis.","Cranberry: proteção antioxidante e um toque azedinho.","Beterraba em pó: cor linda e nitratos naturais para a circulação.","Tâmaras: doçura natural com minerais e fibras."],"yield":"12–14 bolinhas","preview":["1 xícara de farinha de amêndoas","½ xícara de coco ralado","½ xícara de cerejas frescas sem caroço","½ xícara de morangos frescos picados"],"search":"amêndoas baunilha beterraba caroço cerejas coco cranberry desidratado extrato farinha flocos framboesa frescas frescos liofilizada macias morangos natural ralado tâmaras","count":9},"en":{"title":"Tangy Red Berry Bliss Balls","subtitle":"jewel-like treats with cherry, strawberry, cranberry and beet","summary":"Raw almond and coconut bites, red with cherries and strawberries, rolled in raspberry. Twenty minutes, no oven, and they are the first thing to disappear from a Christmas table.","story":"Red berries are nature''s little gems: vibrant, tangy and bursting with flavor. In medieval Europe, strawberries were associated with Venus, symbolizing love and beauty, while cherries were grown in monasteries for both the kitchen and medicine.\n\nTheir bright red hues signal anthocyanins. Cherries are rich in melatonin, cranberries add a tangy zing, and beet powder brings a subtle earthy sweetness and that deep color.\n\nThese bliss balls are like little edible jewels: a treat that connects us to centuries of berry-loving tradition while nourishing your body today.","benefits":["Cherries: antioxidants and melatonin, for sleep and recovery.","Strawberries: vitamin C, fiber and polyphenols.","Cranberries: antioxidant protection and a tangy zing.","Beet powder: a gorgeous color and natural nitrates for circulation.","Dates: natural sweetness with minerals and fiber."],"yield":"Makes 12–14 balls","preview":["1 cup almond flour","½ cup shredded coconut","½ cup fresh cherries, pitted","½ cup fresh strawberries, chopped"],"search":"almond beet cherries coconut cranberries dates dried extract flakes flour freeze natural pitted powder raspberry shredded soft strawberries vanilla","count":9}}'::jsonb
ON CONFLICT (slug) DO NOTHING;
INSERT INTO public.journal_recipe_bodies (recipe_id, body)
SELECT id, '{"pt":{"sections":[{"name":"Base e recheio","ingredients":["1 xícara de farinha de amêndoas","½ xícara de coco ralado","½ xícara de cerejas frescas sem caroço","½ xícara de morangos frescos picados","8 tâmaras macias sem caroço","2 colheres (sopa) de cranberry desidratado","½ colher (chá) de extrato natural de baunilha","1 colher (sopa) de beterraba em pó","100 g de framboesa liofilizada em flocos"],"steps":["No processador, bata as cerejas, os morangos, as tâmaras, o cranberry, a baunilha e a beterraba em pó até ficar homogêneo.","Acrescente a farinha de amêndoas e o coco ralado e vá pulsando até a mistura virar uma massa grudenta.","Pegue porções pequenas e enrole bolinhas do tamanho de uma mordida.","Passe cada bolinha nos flocos de framboesa liofilizada, pressionando de leve para grudar.","Leve à geladeira ou ao freezer por 30 minutos antes de servir, para firmar um pouco."]}],"notes":"Fora da época de cereja, use cereja congelada (descongelada e bem escorrida) ou mais morango.","storage":"Geladeira, em pote fechado, por até 5 dias, ou freezer por até 1 mês."},"en":{"sections":[{"name":"Base and filling","ingredients":["1 cup almond flour","½ cup shredded coconut","½ cup fresh cherries, pitted","½ cup fresh strawberries, chopped","8 soft pitted dates","2 tbsp dried cranberries","½ tsp natural vanilla extract","1 tbsp beet powder","100 g freeze-dried raspberry flakes"],"steps":["In a food processor, blend the cherries, strawberries, dates, cranberries, vanilla and beet powder until smooth.","Add the almond flour and shredded coconut, pulsing until the mixture comes together into a sticky dough.","Scoop out small portions and roll into bite-sized balls.","Coat each ball with the freeze-dried raspberry flakes, pressing gently to adhere.","Chill for 30 minutes in the fridge or freezer before serving, to firm up slightly."]}],"notes":"Out of cherry season, use frozen cherries (thawed and well drained) or more strawberries.","storage":"Fridge, in a closed container, for up to 5 days, or freezer for up to 1 month."}}'::jsonb FROM public.journal_recipes WHERE slug = 'bliss-balls-frutas-vermelhas'
ON CONFLICT (recipe_id) DO NOTHING;

-- Cheesecake da Longevidade de Batata-Doce Roxa
INSERT INTO public.journal_recipes (slug, slug_en, status, publish_at, is_free, price_brl, is_featured, sort, hero_url, gallery, prep_minutes, cook_minutes, chill_minutes, difficulty, categories, tags, contains, text)
SELECT 'cheesecake-longevidade-batata-doce-roxa', 'purple-sweet-potato-longevity-cheesecake', 'published', now() - interval '30 minutes', false, 14.9, false, 40, '/ebook/sweet-escape/purple.webp', ARRAY['/ebook/sweet-escape/purple-whole.webp']::text[], 30, 45, 240, 'media', ARRAY['cheesecakes', 'festas', 'outono', 'sem-trigo', 'sos-free']::text[], ARRAY['Sweet Escape', 'Zonas Azuis', 'Frutas silvestres']::text[], ARRAY['castanhas', 'soja', 'aveia']::text[],
    '{"pt":{"title":"Cheesecake da Longevidade de Batata-Doce Roxa","subtitle":"com frutas silvestres escuras e inspiração nas Zonas Azuis","summary":"Uma base de nozes e cacau, um creme roxo de batata-doce, tofu e mirtilo, e uma calda de amora por cima. Cremoso como cheesecake, sem laticínio nenhum.","story":"A batata-doce roxa não é apenas incrivelmente vibrante: é uma potência de antioxidantes, principalmente antocianinas. Cultivada há milhares de anos nas Américas do Sul e Central, era valorizada pelos povos indígenas por ser nutritiva e durar muito tempo armazenada.\n\nAs frutas silvestres escuras, como mirtilo e amora, eram coletadas por culturas antigas pelo sabor e pelas propriedades medicinais, e usadas até como corante natural.\n\nJuntas, criam um cheesecake que é ao mesmo tempo um mimo e profundamente nutritivo, inspirado nas Zonas Azuis, as regiões do mundo onde as pessoas vivem mais e com mais saúde.","benefits":["Batata-doce roxa: antocianinas e fibras para o coração, o cérebro e os olhos.","Mirtilo e amora: antioxidantes e polifenóis.","Nozes: ômega-3 vegetal.","Tofu: proteína vegetal e saciedade.","Cacau: antioxidante e bom para o humor."],"yield":"8–10 porções","preview":["1 xícara de nozes","¾ xícara de aveia","10 tâmaras macias sem caroço","1 colher (chá) de canela"],"search":"amoras aveia batata baunilha cacau canela caroço doce extrato frescas frescos macias macio mirtilos média natural nozes roxa tofu tâmaras água","count":17},"en":{"title":"Purple Sweet Potato Longevity Cheesecake","subtitle":"with dark forest berries and Blue Zones inspiration","summary":"A walnut and cacao crust, a purple cream of sweet potato, tofu and blueberries, and a blackberry sauce on top. Creamy like cheesecake, with no dairy at all.","story":"Purple sweet potatoes are not only stunningly vibrant, they are a powerhouse of antioxidants, especially anthocyanins. Cultivated for thousands of years in South and Central America, they were prized by Indigenous peoples for being nourishing and keeping for a long time.\n\nDark berries like blueberries and blackberries were foraged by ancient cultures for their flavor and medicinal properties, and even used as natural dyes.\n\nTogether they make a cheesecake that is both indulgent and deeply nourishing, inspired by the Blue Zones, the regions of the world where people live the longest, healthiest lives.","benefits":["Purple sweet potato: anthocyanins and fiber for heart, brain and eyes.","Blueberries and blackberries: antioxidants and polyphenols.","Walnuts: plant-based omega-3.","Tofu: plant protein and satiety.","Cacao: antioxidant-rich and mood-boosting."],"yield":"Serves 8–10","preview":["1 cup walnuts","¾ cup oats","10 soft pitted dates","1 tsp cinnamon"],"search":"blackberries blueberries cacao cinnamon consistency dates extract natural oats pitted potato powder purple soft sweet tofu vanilla walnuts water","count":17}}'::jsonb
ON CONFLICT (slug) DO NOTHING;
INSERT INTO public.journal_recipe_bodies (recipe_id, body)
SELECT id, '{"pt":{"sections":[{"name":"Base","ingredients":["1 xícara de nozes","¾ xícara de aveia","10 tâmaras macias sem caroço","1 colher (chá) de canela","1 colher (chá) de extrato natural de baunilha","1–2 colheres (sopa) de cacau em pó"],"steps":["Preaqueça o forno a 180 °C se for assar levemente a base, ou faça a versão crua.","Bata as nozes, a aveia, as tâmaras, a canela, a baunilha e o cacau no processador até formar uma massa grudenta.","Pressione bem no fundo de uma forma de bolo de silicone ou forrada com papel-manteiga e reserve."]},{"name":"Camada de cheesecake","ingredients":["1 xícara de tofu macio","1 batata-doce roxa média (assada com casca até amolecer, só a polpa)","½ xícara de mirtilos frescos","½ xícara de amoras frescas","8 tâmaras macias","1 colher (chá) de extrato natural de baunilha"],"steps":["Bata a batata-doce assada, o tofu, as tâmaras, as frutas e a baunilha até ficar liso e cremoso.","Despeje sobre a base pronta e alise o topo.","Leve à geladeira por pelo menos 3–4 horas, ou até firmar."]},{"name":"Cobertura de frutas silvestres","ingredients":["½ xícara de mirtilos","½ xícara de amoras","4–5 tâmaras macias","½ colher (chá) de extrato de baunilha","Água, o quanto baste para dar o ponto"],"steps":["Bata as frutas, as tâmaras e a baunilha, acrescentando água aos poucos até virar uma calda fluida.","Espalhe com uma colher sobre o cheesecake gelado antes de servir."]}],"notes":"A batata-doce assa em cerca de 45 minutos a 200 °C. Dá para assar na véspera.","storage":"Geladeira, coberto, por até 4 dias. Sem a calda, congela em fatias por até 1 mês."},"en":{"sections":[{"name":"Crust","ingredients":["1 cup walnuts","¾ cup oats","10 soft pitted dates","1 tsp cinnamon","1 tsp natural vanilla extract","1–2 tbsp cacao powder"],"steps":["Preheat the oven to 180 °C (350 °F) if lightly baking the crust, or make it raw.","Blend the walnuts, oats, dates, cinnamon, vanilla and cacao powder in a food processor until a sticky dough forms.","Press firmly into the base of a parchment-lined or silicone cake pan and set aside."]},{"name":"Cheesecake layer","ingredients":["1 cup soft tofu","1 medium purple sweet potato (baked in its peel until soft, flesh scooped out)","½ cup fresh blueberries","½ cup fresh blackberries","8 soft dates","1 tsp natural vanilla extract"],"steps":["Blend the baked sweet potato, tofu, dates, berries and vanilla until smooth and creamy.","Pour over the crust and smooth the top.","Chill in the fridge for at least 3–4 hours, or until firm."]},{"name":"Berry topping","ingredients":["½ cup blueberries","½ cup blackberries","4–5 soft dates","½ tsp vanilla extract","Water as needed for consistency"],"steps":["Blend the berries, dates and vanilla, adding water gradually to make a pourable sauce.","Spoon over the chilled cheesecake before serving."]}],"notes":"The sweet potato bakes in about 45 minutes at 200 °C (400 °F). You can bake it the day before.","storage":"Fridge, covered, for up to 4 days. Without the sauce it freezes in slices for up to 1 month."}}'::jsonb FROM public.journal_recipes WHERE slug = 'cheesecake-longevidade-batata-doce-roxa'
ON CONFLICT (recipe_id) DO NOTHING;

-- Sanduíches de Sorvete de Pistache Supergreen Laguna
INSERT INTO public.journal_recipes (slug, slug_en, status, publish_at, is_free, price_brl, is_featured, sort, hero_url, gallery, prep_minutes, cook_minutes, chill_minutes, difficulty, categories, tags, contains, text)
SELECT 'sanduiche-de-sorvete-pistache-laguna', 'supergreen-laguna-pistachio-ice-cream-sandwiches', 'published', now() - interval '20 minutes', false, 12.9, false, 50, '/ebook/sweet-escape/green.webp', ARRAY['/ebook/sweet-escape/green-side.webp']::text[], 20, 12, 0, 'facil', ARRAY['verao', 'cookies', 'lanche-infantil', 'sem-trigo', 'sos-free']::text[], ARRAY['Sweet Escape', 'Nicecream', 'Pistache']::text[], ARRAY['castanhas']::text[],
    '{"pt":{"title":"Sanduíches de Sorvete de Pistache Supergreen Laguna","subtitle":"uma delícia alegre e derretida, turbinada com espirulina","summary":"Biscoitinhos verdes de pistache e amêndoa com uma bola de nicecream de banana no meio. O sorvete das crianças que não leva nada além de fruta.","story":"Verde é a cor da vitalidade, do equilíbrio e da renovação. A espirulina, uma alga verde-azulada, é consumida há séculos: dos astecas, que a colhiam no Lago Texcoco, às comunidades às margens do Lago Chade, onde era seca e chamada de dihé.\n\nNesta receita, vamos nos deliciar com o que os veganos chamam de nicecream: aquele milagre de sorvete cremoso que nasce só de congelar e bater banana. Junto com o pistache, vira uma celebração do verde.\n\nA inspiração vem das lagoas tropicais, onde a água brilha em tons de esmeralda e verde-azulado.","benefits":["Espirulina: proteína, ferro, vitaminas do complexo B e clorofila.","Pistache: gorduras boas, proteína e fibras.","Banana: doçura natural e potássio.","Farinha de amêndoas: proteína vegetal e saciedade.","Uvas-passas brancas: doçura suave, com ferro e minerais."],"yield":"6–8 sanduíches","preview":["¾ xícara de farinha de amêndoas","½ xícara de pistache picado grosso","1 colher (chá) de espirulina em pó","¼ xícara de uvas-passas brancas"],"search":"amêndoas bananas baunilha brancas congeladas espirulina extrato farinha grosso natural passas pistache polvilhar punhadinho rodelas triturado uvas","count":10},"en":{"title":"Supergreen Laguna Pistachio Ice Cream Sandwiches","subtitle":"a joyful melting spirulina-powered treat","summary":"Little green pistachio and almond cookies with a scoop of banana nicecream in between. The kids'' ice cream made of nothing but fruit.","story":"Green is the color of vitality, balance and renewal. Spirulina, a blue-green algae, has been eaten for centuries: from the Aztecs who harvested it from Lake Texcoco, to the communities along Lake Chad, where it was dried and called dihé.\n\nWith this recipe we indulge in what vegans call nicecream: the soft-serve miracle that comes from simply freezing and blending bananas. With pistachios it becomes a celebration of green.\n\nThe inspiration comes from tropical lagoons, where the water shimmers in shades of emerald and teal.","benefits":["Spirulina: protein, iron, B vitamins and chlorophyll.","Pistachios: healthy fats, protein and fiber.","Bananas: natural sweetness and potassium.","Almond flour: plant protein and satiety.","White raisins: gentle sweetness with iron and minerals."],"yield":"Makes 6–8 sandwiches","preview":["¾ cup almond flour","½ cup pistachios, roughly chopped","1 tsp spirulina powder","¼ cup white raisins"],"search":"almond bananas crushed extract flour frozen handful natural pistachios powder raisins roughly sliced spirulina sprinkle vanilla white","count":10}}'::jsonb
ON CONFLICT (slug) DO NOTHING;
INSERT INTO public.journal_recipe_bodies (recipe_id, body)
SELECT id, '{"pt":{"sections":[{"name":"Biscoitos de pistache","ingredients":["¾ xícara de farinha de amêndoas","½ xícara de pistache picado grosso","1 colher (chá) de espirulina em pó","¼ xícara de uvas-passas brancas","1 colher (chá) de extrato natural de baunilha","Opcional: um punhadinho de pistache triturado para polvilhar"],"steps":["Preaqueça o forno a 175 °C e forre uma assadeira com papel-manteiga.","Misture a farinha de amêndoas, o pistache, a espirulina, as passas e a baunilha até formar uma massa grudenta.","Modele biscoitinhos triangulares e coloque na assadeira. Polvilhe pistache triturado por cima.","Asse por 10–12 minutos, até as bordas dourarem levemente: crocante por fora, macio por dentro.","Deixe esfriar completamente antes de montar."]},{"name":"Recheio de nicecream","ingredients":["2–3 bananas congeladas em rodelas","½ colher (chá) de extrato natural de baunilha","½ colher (chá) de espirulina em pó","Opcional: 1–2 colheres (sopa) de uvas-passas brancas"],"steps":["Bata as bananas congeladas, a espirulina e a baunilha até ficar liso e cremoso, como sorvete de máquina. Se quiser, misture as passas.","Coloque uma boa colherada de nicecream entre dois biscoitos.","Coma na hora: a ideia é se lambuzar e se divertir!"]}],"notes":"Quanto mais madura a banana antes de congelar, mais doce fica o nicecream.","storage":"Os biscoitos duram 4 dias num pote fechado. Monte os sanduíches na hora, ou congele já montados, embrulhados um a um, por até 2 semanas."},"en":{"sections":[{"name":"Pistachio sandwich cookies","ingredients":["¾ cup almond flour","½ cup pistachios, roughly chopped","1 tsp spirulina powder","¼ cup white raisins","1 tsp natural vanilla extract","Optional: a small handful of crushed pistachios to sprinkle on top"],"steps":["Preheat the oven to 175 °C (350 °F) and line a baking sheet with parchment.","Mix the almond flour, pistachios, spirulina, raisins and vanilla until a sticky dough forms.","Shape into small triangular cookies and place on the baking sheet. Sprinkle crushed pistachios on top.","Bake for 10–12 minutes until the edges are lightly golden: crunchy outside, soft inside.","Cool completely before assembling."]},{"name":"Nicecream filling","ingredients":["2–3 frozen bananas, sliced","½ tsp natural vanilla extract","½ tsp spirulina powder","Optional: 1–2 tbsp white raisins"],"steps":["Blend the frozen bananas, spirulina and vanilla until smooth and creamy, like soft-serve ice cream. Fold in the raisins if you like.","Sandwich a generous scoop of nicecream between two cookies.","Eat immediately: this is meant to be a jolly, melting experience!"]}],"notes":"The riper the bananas before freezing, the sweeter the nicecream.","storage":"The cookies keep 4 days in a closed container. Assemble just before eating, or freeze assembled sandwiches, wrapped one by one, for up to 2 weeks."}}'::jsonb FROM public.journal_recipes WHERE slug = 'sanduiche-de-sorvete-pistache-laguna'
ON CONFLICT (recipe_id) DO NOTHING;

-- Barrinhas Banoffee de Amendoim
INSERT INTO public.journal_recipes (slug, slug_en, status, publish_at, is_free, price_brl, is_featured, sort, hero_url, gallery, prep_minutes, cook_minutes, chill_minutes, difficulty, categories, tags, contains, text)
SELECT 'barrinhas-banoffee-de-amendoim', 'peanutty-banoffee-bars', 'published', now() - interval '10 minutes', true, 12.9, false, 60, '/ebook/sweet-escape/caramel.webp', ARRAY['/ebook/sweet-escape/caramel-close.webp']::text[], 25, 0, 180, 'facil', ARRAY['brownies-barrinhas', 'lanche-infantil', 'festas', 'cru', 'sem-forno', 'sem-trigo', 'sos-free']::text[], ARRAY['Sweet Escape', 'Amendoim', 'Caramelo de tâmara']::text[], ARRAY['amendoim', 'castanhas']::text[],
    '{"pt":{"title":"Barrinhas Banoffee de Amendoim","subtitle":"um doce cru de três camadas unindo o Brasil e a Inglaterra","summary":"Uma base de paçoca de tâmara, um creme de banana com caju e uma calda de caramelo de tâmara por cima. Três camadas, nenhum forno, gosto de infância.","story":"No Brasil, o amendoim tem raízes profundas na culinária indígena e é amado em doces que dão saudade, como a paçoca, o doce de amendoim e o pé de moleque.\n\nQuando me mudei para o Brasil, descobrir a paçoca foi como encontrar uma parte de mim que eu nem sabia que faltava. Para fazer uma versão mais saudável, logo soube que era só trocar o açúcar por tâmaras. E pode acreditar: a minha paçoca tem o mesmo gostinho doce e intenso.\n\nDo outro lado do oceano, na Inglaterra, nasceu a banoffee pie: banana, creme e toffee. Estas barrinhas unem a abundância tropical do Brasil ao aconchego da Europa. É uma sobremesa com sabor de casa, não importa onde fique essa casa.","benefits":["Amendoim: proteína vegetal e gorduras boas.","Banana: potássio, fibras e doçura natural.","Castanha-de-caju: cremosidade e magnésio.","Tâmaras: sabor natural de caramelo, com minerais.","Canela: notas aconchegantes, boa para a digestão."],"yield":"8–10 barrinhas","preview":["1 xícara de amendoim torrado sem sal","½ xícara de tâmaras macias sem caroço","1 colher (chá) de extrato natural de baunilha"],"search":"amendoim banana baunilha caju canela caroço castanhas extrato grande macias natural torrado tâmaras água","count":11},"en":{"title":"Peanutty Banoffee Bars","subtitle":"a raw, three-layer treat bridging Brazil and Britain","summary":"A date ''paçoca'' peanut base, a banana and cashew cream and a date caramel on top. Three layers, no oven, and a taste of childhood.","story":"In Brazil, peanuts have deep roots in Indigenous cuisine and are beloved in nostalgic sweets like paçoca, doce de amendoim and pé de moleque.\n\nWhen I moved to Brazil, discovering paçoca felt like uncovering a part of myself I didn''t know I was missing. To make a healthier version, I knew to replace the sugar with dates. And trust me, my paçoca delivered the same sweet, rich delight.\n\nAcross the ocean, in Britain, the banoffee pie was born: banana, cream and toffee. These bars bring the tropical abundance of Brazil together with the comfort of Europe. A dessert that feels like home, no matter where that home is.","benefits":["Peanuts: plant protein and healthy fats.","Bananas: potassium, fiber and natural sweetness.","Cashews: creaminess and magnesium.","Dates: a natural caramel flavor, with minerals.","Cinnamon: warming and good for digestion."],"yield":"Makes 8–10 bars","preview":["1 cup roasted unsalted peanuts","½ cup soft pitted dates","1 tsp natural vanilla extract"],"search":"banana cashews cinnamon dates extract natural peanuts pitted roasted soft unsalted vanilla water","count":11}}'::jsonb
ON CONFLICT (slug) DO NOTHING;
INSERT INTO public.journal_recipe_bodies (recipe_id, body)
SELECT id, '{"pt":{"sections":[{"name":"Base","ingredients":["1 xícara de amendoim torrado sem sal","½ xícara de tâmaras macias sem caroço","1 colher (chá) de extrato natural de baunilha"],"steps":["Bata o amendoim, as tâmaras e a baunilha no processador até virar uma farofa úmida que gruda.","Pressione bem em uma forma retangular forrada com papel-manteiga. Reserve enquanto prepara a próxima camada."]},{"name":"Camada do meio: banana e caju","ingredients":["1 banana grande e madura","½ xícara de castanhas-de-caju (de molho por 4–6 horas ou em água quente por 15 minutos, depois escorridas)","½ xícara de tâmaras macias sem caroço","½ colher (chá) de canela","1 colher (chá) de extrato natural de baunilha"],"steps":["Bata a banana, as castanhas, as tâmaras, a canela e a baunilha até ficar liso e cremoso.","Espalhe por igual sobre a base de amendoim. Leve à geladeira para firmar um pouco antes da última camada."]},{"name":"Camada de caramelo","ingredients":["½ xícara de tâmaras macias sem caroço","½ colher (chá) de extrato de baunilha","2–3 colheres (sopa) de água (ajuste até a calda ficar no ponto que você gosta)"],"steps":["Bata as tâmaras, a baunilha e a água até formar uma calda de caramelo lisa e fluida.","Despeje sobre a camada do meio, espalhando por igual.","Leve à geladeira por 2–3 horas, ou até firmar o suficiente para cortar em barrinhas."]}],"notes":"Para as crianças, polvilhe um pouco de amendoim picado por cima do caramelo: fica com cara de doce de festa.","storage":"Geladeira, em pote fechado, por até 4 dias, ou freezer por até 1 mês."},"en":{"sections":[{"name":"Base layer","ingredients":["1 cup roasted unsalted peanuts","½ cup soft pitted dates","1 tsp natural vanilla extract"],"steps":["Blend the peanuts, dates and vanilla in a food processor until sticky and crumbly.","Press firmly into a parchment-lined rectangular dish. Set aside while you make the next layer."]},{"name":"Banana-cashew layer","ingredients":["1 large ripe banana","½ cup cashews (soaked 4–6 hours or in hot water for 15 minutes, then drained)","½ cup soft pitted dates","½ tsp cinnamon","1 tsp natural vanilla extract"],"steps":["Blend the banana, cashews, dates, cinnamon and vanilla until smooth and creamy.","Spread evenly over the peanut base. Chill to set slightly before adding the top layer."]},{"name":"Caramel layer","ingredients":["½ cup soft pitted dates","½ tsp vanilla extract","2–3 tbsp water (adjust for the consistency you like)"],"steps":["Blend the dates, vanilla and water into a smooth, runny caramel sauce.","Pour over the middle layer, spreading evenly.","Chill for 2–3 hours or until firm enough to cut into bars."]}],"notes":"For kids, sprinkle a few chopped peanuts over the caramel: it instantly looks like party food.","storage":"Fridge, in a closed container, for up to 4 days, or freezer for up to 1 month."}}'::jsonb FROM public.journal_recipes WHERE slug = 'barrinhas-banoffee-de-amendoim'
ON CONFLICT (recipe_id) DO NOTHING;

-- Tartarugas de Mousse de Cacau Intenso
INSERT INTO public.journal_recipes (slug, slug_en, status, publish_at, is_free, price_brl, is_featured, sort, hero_url, gallery, prep_minutes, cook_minutes, chill_minutes, difficulty, categories, tags, contains, text)
SELECT 'tartarugas-de-mousse-de-cacau', 'dark-cocoa-mousse-turtles', 'published', now() - interval '0 minutes', false, 14.9, false, 70, '/ebook/sweet-escape/chocolate.webp', ARRAY['/ebook/sweet-escape/chocolate-cut.webp', '/ebook/sweet-escape/choc-triangles.webp']::text[], 40, 0, 135, 'media', ARRAY['chocolate', 'patisserie', 'festas', 'lanche-infantil', 'sem-forno', 'sem-trigo']::text[], ARRAY['Sweet Escape', 'Cacau', 'Pera']::text[], ARRAY['castanhas', 'aveia', 'soja']::text[],
    '{"pt":{"title":"Tartarugas de Mousse de Cacau Intenso","subtitle":"uma ode aveludada ao chocolate, com uma surpresa de pera","summary":"Uma base de pecã e cacau, uma mousse escura que leva pera (o segredo da textura) e uma casquinha de chocolate que estala. Sem ovos, sem creme de leite.","story":"O chocolate percorreu um longo caminho até os nossos corações: bebida sagrada de maias e astecas, depois puro prazer na Europa. A Bélgica se tornou uma das verdadeiras capitais do chocolate, e eu cresci cercada por essa devoção: o aroma de cacau no ar em cada rua.\n\nNeste doce quis honrar essa herança com o meu toque tropical. O ingrediente secreto é a pera: batida crua no processador, ela vira uma mousse firme que derrete na boca como manteiga, sem ovos, creme de leite ou laticínios.\n\nAs tartarugas são uma homenagem à minha casa no Brasil, onde muitas vezes nado ao lado de tartarugas de verdade no mar. Assim como elas, estas têm um casco protetor e um coração macio por dentro.","benefits":["Cacau black: polifenóis e antioxidantes, bom para o humor.","Noz-pecã: gorduras monoinsaturadas, fibras e minerais.","Pera: hidratante e cheia de fibras solúveis.","Tâmaras: o caramelo da natureza, com minerais."],"yield":"6–8 tartarugas","preview":["¾ xícara de nozes-pecã cruas","½ xícara de aveia","6–8 tâmaras macias sem caroço","2 colheres (sopa) de cacau em pó orgânico"],"search":"amargo aveia baunilha black cacau caroço casca chocolate cruas derretido extras extrato macias miolo natural nibs nozes orgânico pecã pera tâmaras vegano","count":13},"en":{"title":"Dark Cocoa Mousse Turtles","subtitle":"a velvet-dark ode to chocolate, with a surprising pear","summary":"A pecan and cacao base, a dark mousse made with pear (the secret to its texture) and a chocolate shell that cracks. No eggs, no cream.","story":"Chocolate has traveled a long road into our hearts: a sacred drink of the Maya and Aztecs, then pure pleasure in Europe. Belgium became one of the world''s true chocolate capitals, and I grew up surrounded by that devotion, the scent of cocoa in every street.\n\nIn this treat I wanted to honor that heritage with my own tropical twist. My secret ingredient is pear: blended raw, it turns into a mousse that is firm yet melts like butter in your mouth, without eggs, cream or dairy.\n\nThe turtles are a nod to my home in Brazil, where I often swim alongside real turtles in the ocean. Just like them, these have a protective shell and a soft heart inside.","benefits":["Black cocoa: polyphenols and antioxidants, good for your mood.","Pecans: monounsaturated fats, fiber and minerals.","Pear: hydrating and full of soluble fiber.","Dates: nature''s caramel, with minerals."],"yield":"Makes 6–8 turtles","preview":["¾ cup raw pecans","½ cup oats","6–8 soft dates, pitted","2 tbsp organic cocoa powder"],"search":"black chocolate cocoa cored dark dates extra extract melted natural nibs oats organic pear pecans peeled pitted powder soft vanilla vegan","count":13}}'::jsonb
ON CONFLICT (slug) DO NOTHING;
INSERT INTO public.journal_recipe_bodies (recipe_id, body)
SELECT id, '{"pt":{"sections":[{"name":"Base","ingredients":["¾ xícara de nozes-pecã cruas","½ xícara de aveia","6–8 tâmaras macias sem caroço","2 colheres (sopa) de cacau em pó orgânico","1 colher (chá) de extrato natural de baunilha"],"steps":["Bata todos os ingredientes no processador até formar uma massa grudenta.","Com os dedos, modele pequenas bases ovais (cerca de ½ cm de espessura) sobre uma assadeira forrada com papel-manteiga: esse é o corpo da tartaruga.","Leve ao freezer enquanto prepara a mousse."]},{"name":"Camada de mousse","ingredients":["1 pera madura, sem casca e sem miolo","3–4 tâmaras macias","2 colheres (sopa) de cacau black em pó","2 colheres (sopa) de chocolate amargo vegano derretido*","1 colher (chá) de extrato de baunilha"],"steps":["Bata todos os ingredientes até ficar liso e cremoso. A pera dá a textura sedosa e aerada.","Com uma colher ou saco de confeitar, coloque a mousse sobre cada base, em formato arredondado de casco.","Congele por cerca de 2 horas para firmar."]},{"name":"Casca de chocolate","ingredients":["½ xícara de chocolate amargo vegano derretido*","1 colher (sopa) de nibs de cacau (para decorar)"],"steps":["Espalhe ou regue o chocolate derretido sobre os cascos de mousse já firmes, criando um escudo liso e brilhante.","Polvilhe os nibs de cacau antes de endurecer."]},{"name":"Montagem (a parte divertida!)","ingredients":["Nozes-pecã extras"],"steps":["Use as nozes-pecã para fazer cabecinhas, bracinhos e patinhas ao redor de cada tartaruga. Pressione de leve antes que a casca firme totalmente.","Leve de volta à geladeira por 15 minutos e sirva."]}],"notes":"*O chocolate amargo vegano da receita original foi adoçado com tâmaras. A maioria dos chocolates veganos do mercado contém açúcar refinado (e muitos levam lecitina de soja): confira o rótulo se quiser a receita 100% SOS-free.","storage":"Geladeira por até 4 dias, ou freezer por até 1 mês. Tire 10 minutos antes de servir."},"en":{"sections":[{"name":"Base layer","ingredients":["¾ cup raw pecans","½ cup oats","6–8 soft dates, pitted","2 tbsp organic cocoa powder","1 tsp natural vanilla extract"],"steps":["Blend all ingredients in a food processor until a sticky dough forms.","With your fingers, form small oval bases (about ½ cm thick) on a parchment-lined tray: these are the turtles'' bodies.","Place in the freezer while you make the mousse."]},{"name":"Mousse layer","ingredients":["1 ripe pear, peeled and cored","3–4 soft dates","2 tbsp black cocoa powder","2 tbsp melted dark vegan chocolate*","1 tsp vanilla extract"],"steps":["Blend all ingredients until smooth and creamy. The pear gives the mousse its silky, whipped texture.","Spoon or pipe the mousse on top of each base in a rounded turtle-shell shape.","Freeze for about 2 hours to firm up."]},{"name":"Chocolate shell","ingredients":["½ cup dark vegan chocolate, melted*","1 tbsp cocoa nibs (to decorate)"],"steps":["Spoon or drizzle the melted chocolate over the firm mousse shells to make a smooth, glossy shield.","Sprinkle with cocoa nibs before it sets."]},{"name":"Assembly (the fun part!)","ingredients":["Extra pecans"],"steps":["Use the pecans to make tiny heads, arms and feet around each turtle. Press gently before the shell fully sets.","Return to the fridge for 15 minutes, then serve."]}],"notes":"*The dark vegan chocolate in the original recipe was sweetened with dates. Most vegan dark chocolates in shops contain refined sugar (and many contain soy lecithin), so check the label if you want the recipe fully SOS-free.","storage":"Fridge for up to 4 days, or freezer for up to 1 month. Take out 10 minutes before serving."}}'::jsonb FROM public.journal_recipes WHERE slug = 'tartarugas-de-mousse-de-cacau'
ON CONFLICT (recipe_id) DO NOTHING;

INSERT INTO public.journal_collections (slug, published, price_brl, cover_url, sort, text)
VALUES ('sweet-escape-7-cores', false, 39.90, '/ebook/sweet-escape/yellow-plate.webp', 10, '{"pt":{"title":"Sweet Escape: 7 cores, 7 receitas","summary":"As sete receitas do livro, uma para cada cor do arco-íris.","description":"Do amarelo do abacaxi ao escuro do cacau: as sete receitas do Sweet Escape, com a história de cada fruta e o passo a passo completo."},"en":{"title":"Sweet Escape: 7 colors, 7 recipes","summary":"All seven recipes from the book, one for every color of the rainbow.","description":"From pineapple yellow to cocoa dark: the seven Sweet Escape recipes, with the story of each fruit and every step."}}'::jsonb)
ON CONFLICT (slug) DO NOTHING;
INSERT INTO public.journal_collection_recipes (collection_id, recipe_id, sort)
SELECT c.id, r.id, r.sort FROM public.journal_collections c, public.journal_recipes r
WHERE c.slug = 'sweet-escape-7-cores' AND r.slug IN ('quadradinhos-paraiso-coco-abacaxi', 'muffins-de-manga-chai', 'bliss-balls-frutas-vermelhas', 'cheesecake-longevidade-batata-doce-roxa', 'sanduiche-de-sorvete-pistache-laguna', 'barrinhas-banoffee-de-amendoim', 'tartarugas-de-mousse-de-cacau')
ON CONFLICT DO NOTHING;

COMMIT;

-- Check: 20 categories, 7 recipes (2 free), 7 bodies, 1 collection.
SELECT
    (SELECT count(*) FROM public.journal_categories) AS categories,
    (SELECT count(*) FROM public.journal_recipes) AS recipes,
    (SELECT count(*) FROM public.journal_recipes WHERE is_free) AS free_recipes,
    (SELECT count(*) FROM public.journal_recipe_bodies) AS bodies,
    (SELECT count(*) FROM public.journal_collections) AS collections;
